import sys


def main():
    values = map(int, sys.stdin.buffer.read().split())
    n = next(values)
    x = next(values)

    frequencies = [1]
    for value in values:
        if value < x:
            frequencies.append(1)
        else:
            frequencies[-1] += 1

    count = len(frequencies) - 1
    square_sum = sum(value * value for value in frequencies)
    answers = [str((square_sum - n - 1) // 2)]

    if count == 0:
        answers.extend(["0"] * n)
        sys.stdout.write(" ".join(answers))
        return

    if all(value == frequencies[0] for value in frequencies):
        factor = frequencies[0] ** 2
        answers.extend(str((count + 1 - k) * factor)
                       for k in range(1, count + 1))
    else:
        width = (square_sum.bit_length() + 7) // 8

        forward = int.from_bytes(
            b"".join(value.to_bytes(width, "little")
                     for value in frequencies),
            "little",
        )
        backward = int.from_bytes(
            b"".join(value.to_bytes(width, "little")
                     for value in reversed(frequencies)),
            "little",
        )

        product = forward * backward
        product >>= (count + 1) * width * 8
        coefficients = memoryview(product.to_bytes(count * width, "little"))

        answers.extend(
            str(int.from_bytes(coefficients[offset:offset + width], "little"))
            for offset in range(0, count * width, width)
        )

    answers.extend(["0"] * (n - count))
    sys.stdout.write(" ".join(answers))


if __name__ == "__main__":
    main()
